LIMIT = 100


def prime_flags(limit):
    """Sieve of Eratosthenes: flags[k] is True when k is prime.
    (Once you need it twice, move it into your helpers.)"""
    flags = [True] * (limit + 1)
    flags[0] = flags[1] = False
    for p in range(2, int(limit ** 0.5) + 1):
        if flags[p]:
            for multiple in range(p * p, limit + 1, p):
                flags[multiple] = False
    return flags


def solve():
    is_prime = prime_flags(LIMIT)      # one pass fills the whole table
    # Every question is now a list lookup. Example: twin primes (p, p + 2) below 100.
    return sum(1 for p in range(2, LIMIT - 1) if is_prime[p] and is_prime[p + 2])


